#!/usr/bin/env python3
"""
Flexible Job-Shop Scheduling Problem (FJSP) Solver
with downtime constraints, policy freeze, and change budgets.

Key insight: Downtime is a HARD physical constraint. Freeze policy is a soft
preference that must yield when it conflicts with downtime. Operations frozen
in baseline that overlap downtime must be rescheduled.
"""

import json
import csv
import os
import itertools
from copy import deepcopy

###############################################################################
# PARSING
###############################################################################
def parse_instance(path):
    with open(path) as f:
        lines = [l.strip() for l in f if l.strip()]
    idx = 0
    n_jobs, n_machines = map(int, lines[idx].split())
    idx += 1
    jobs = []
    for j in range(n_jobs):
        n_ops = int(lines[idx]); idx += 1
        ops = []
        for o in range(n_ops):
            tokens = list(map(int, lines[idx].split())); idx += 1
            n_choices = tokens[0]
            choices = [(tokens[1+2*c], tokens[2+2*c]) for c in range(n_choices)]
            ops.append(choices)
        jobs.append(ops)
    return n_jobs, n_machines, jobs

def parse_downtime(path):
    downtime = {}
    with open(path) as f:
        reader = csv.DictReader(f)
        for row in reader:
            m, s, e = int(row['machine']), int(row['start']), int(row['end'])
            downtime.setdefault(m, []).append((s, e))
    return downtime

def parse_policy(path):
    with open(path) as f:
        return json.load(f)

def parse_baseline(path):
    with open(path) as f:
        return json.load(f)

###############################################################################
# HELPERS
###############################################################################
def overlaps_downtime(machine, start, end, downtime):
    for ds, de in downtime.get(machine, []):
        if start < de and end > ds:
            return True
    return False

def find_slot_on_machine(machine, earliest, duration, machine_timeline, downtime):
    """Find the earliest start >= earliest for a duration-length slot on machine,
    avoiding downtime and existing scheduled operations."""
    start = earliest
    for _ in range(2000):
        end = start + duration
        # Check downtime
        conflict = False
        for ds, de in sorted(downtime.get(machine, [])):
            if start < de and end > ds:
                start = de
                conflict = True
                break
        if conflict:
            continue
        # Check machine timeline
        conflict = False
        for ms, me in sorted(machine_timeline):
            if start < me and end > ms:
                start = me
                conflict = True
                break
        if conflict:
            continue
        return start
    return start

def build_baseline_lookup(baseline):
    return {(e['job'], e['op']): e for e in baseline['schedule']}

###############################################################################
# DETERMINE TRULY FROZEN OPS (frozen AND feasible with downtime)
###############################################################################
def get_frozen_ops(baseline, policy, downtime):
    """Return dict of (job,op)->entry for ops that are frozen AND don't violate downtime.
    Ops that are frozen but violate downtime must be rescheduled (downtime is hard constraint)."""
    freeze = policy.get('freeze', {})
    if not freeze.get('enabled', False):
        return {}

    freeze_until = freeze.get('freeze_until', 0)
    frozen = {}
    unfrozen_due_to_downtime = []

    for entry in baseline['schedule']:
        if entry['start'] < freeze_until:
            m = entry['machine']
            if not overlaps_downtime(m, entry['start'], entry['end'], downtime):
                frozen[(entry['job'], entry['op'])] = entry
            else:
                unfrozen_due_to_downtime.append(entry)

    if unfrozen_due_to_downtime:
        print("Ops unfrozen due to downtime conflict:")
        for e in unfrozen_due_to_downtime:
            print(f"  Job {e['job']} Op {e['op']} machine {e['machine']} [{e['start']},{e['end']})")

    return frozen

###############################################################################
# SCHEDULE WITH FIXED ASSIGNMENT + PERMUTATION ORDERING
###############################################################################
def schedule_with_assignment_and_order(jobs, n_machines, downtime, frozen_ops,
                                        assignment, n_jobs, job_order_per_level):
    """
    Schedule with:
    - frozen_ops placed as-is
    - assignment dict for non-frozen ops: (j,o) -> (machine, duration)
    - job_order_per_level: for each op level, the order to schedule jobs
    """
    machine_timeline = {m: [] for m in range(n_machines)}
    job_end_time = {j: 0 for j in range(n_jobs)}
    schedule = []
    scheduled = set()

    # Place frozen ops
    for (j, o), entry in frozen_ops.items():
        se = dict(entry)
        schedule.append(se)
        machine_timeline[entry['machine']].append((entry['start'], entry['end']))
        job_end_time[j] = max(job_end_time[j], entry['end'])
        scheduled.add((j, o))

    # Schedule remaining ops level by level
    max_ops = max(len(j) for j in jobs)
    for o in range(max_ops):
        level_jobs = [j for j in range(n_jobs) if o < len(jobs[j]) and (j, o) not in scheduled]

        # Apply ordering
        if o < len(job_order_per_level):
            order = job_order_per_level[o]
            # Filter to only jobs in level_jobs
            ordered = [j for j in order if j in level_jobs]
            # Add any remaining (shouldn't happen)
            remaining = [j for j in level_jobs if j not in ordered]
            level_jobs = ordered + remaining

        for j in level_jobs:
            # Check precedence
            if o > 0 and (j, o-1) not in scheduled:
                continue  # Can't schedule yet - this shouldn't happen in level-by-level

            m, d = assignment[(j, o)]
            earliest = job_end_time[j]
            start = find_slot_on_machine(m, earliest, d, machine_timeline[m], downtime)
            end = start + d

            schedule.append({
                'job': j, 'op': o, 'machine': m,
                'start': start, 'end': end, 'dur': d
            })
            machine_timeline[m].append((start, end))
            job_end_time[j] = end
            scheduled.add((j, o))

    return schedule

###############################################################################
# COMPREHENSIVE SOLVER
###############################################################################
def solve(jobs, n_machines, downtime, baseline, policy):
    n_jobs = len(jobs)
    bl_lookup = build_baseline_lookup(baseline)

    budget = policy.get('change_budget', {})
    max_machine_changes = budget.get('max_machine_changes', float('inf'))
    max_total_start_shift = budget.get('max_total_start_shift_L1', float('inf'))

    guards = policy.get('guards', {})
    max_makespan_ratio = guards.get('max_makespan_ratio', float('inf'))
    baseline_makespan = baseline['makespan']
    max_allowed_makespan = baseline_makespan * max_makespan_ratio

    frozen_ops = get_frozen_ops(baseline, policy, downtime)
    print(f"\nTruly frozen ops: {list(frozen_ops.keys())}")

    # Build list of ops to assign machines
    ops_to_assign = []
    for j in range(n_jobs):
        for o in range(len(jobs[j])):
            if (j, o) not in frozen_ops:
                ops_to_assign.append((j, o))

    choice_lists = [jobs[j][o] for j, o in ops_to_assign]

    total_combos = 1
    for cl in choice_lists:
        total_combos *= len(cl)
    print(f"Machine assignment combinations: {total_combos}")

    # For job orderings at each level, we'll try permutations
    max_ops = max(len(j) for j in jobs)

    best_schedule = None
    best_makespan = float('inf')
    best_info = {}

    for combo in itertools.product(*choice_lists):
        assignment = {}
        for i, (j, o) in enumerate(ops_to_assign):
            assignment[(j, o)] = combo[i]

        # Also include frozen ops in assignment for completeness
        for (j, o), entry in frozen_ops.items():
            assignment[(j, o)] = (entry['machine'], entry['dur'])

        # Check machine change budget (only count non-frozen)
        machine_changes = 0
        for (j, o) in ops_to_assign:
            m, d = assignment[(j, o)]
            bl_entry = bl_lookup.get((j, o))
            if bl_entry and m != bl_entry['machine']:
                machine_changes += 1

        if machine_changes > max_machine_changes:
            continue

        # Try different job orderings at each level
        # For 4 jobs, there are 4! = 24 permutations per level,
        # and 3 levels = 24^3 = 13824 total. Combined with 128 machine combos
        # that's ~1.7M which is manageable but let's be smarter.
        # First try a few good heuristics, then try all perms for promising combos.

        # Heuristic orderings:
        orderings_to_try = []

        # 1. Sort by earliest available time
        for o_level in range(max_ops):
            pass  # Dynamic, computed during scheduling
        orderings_to_try.append(None)  # Use default (earliest available)

        # Try all permutations for each level
        level_jobs = []
        for o_level in range(max_ops):
            lj = [j for j in range(n_jobs) if o_level < len(jobs[j]) and (j, o_level) not in frozen_ops]
            level_jobs.append(lj)

        # Generate all permutation combos for levels
        perm_lists = [list(itertools.permutations(lj)) if lj else [()] for lj in level_jobs]

        for perm_combo in itertools.product(*perm_lists):
            job_order_per_level = [list(p) for p in perm_combo]

            schedule = schedule_with_assignment_and_order(
                jobs, n_machines, downtime, frozen_ops,
                assignment, n_jobs, job_order_per_level
            )

            if schedule is None or len(schedule) != sum(len(j) for j in jobs):
                continue

            makespan = max(e['end'] for e in schedule)

            if makespan >= best_makespan:
                continue

            if makespan > max_allowed_makespan:
                continue

            # Check start shift budget
            total_shift = sum(
                abs(e['start'] - bl_lookup[(e['job'], e['op'])]['start'])
                for e in schedule if (e['job'], e['op']) in bl_lookup
            )

            if total_shift > max_total_start_shift:
                continue

            # Validate no downtime violations
            valid = True
            for e in schedule:
                if overlaps_downtime(e['machine'], e['start'], e['end'], downtime):
                    valid = False
                    break
            if not valid:
                continue

            # Validate precedence
            job_ops = {}
            for e in schedule:
                job_ops.setdefault(e['job'], []).append(e)
            for j_ops in job_ops.values():
                j_sorted = sorted(j_ops, key=lambda x: x['op'])
                for i in range(1, len(j_sorted)):
                    if j_sorted[i]['start'] < j_sorted[i-1]['end']:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue

            # Validate machine non-overlap
            machine_ops = {}
            for e in schedule:
                machine_ops.setdefault(e['machine'], []).append(e)
            for m_ops in machine_ops.values():
                m_sorted = sorted(m_ops, key=lambda x: x['start'])
                for i in range(1, len(m_sorted)):
                    if m_sorted[i]['start'] < m_sorted[i-1]['end']:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue

            best_makespan = makespan
            best_schedule = schedule
            best_info = {
                'machine_changes': machine_changes,
                'total_shift': total_shift,
            }
            print(f"  New best: makespan={best_makespan}, mc={machine_changes}, shift={total_shift}")

    return best_schedule, best_makespan, best_info

###############################################################################
# VALIDATION
###############################################################################
def validate_schedule(schedule, n_jobs, n_machines, jobs, downtime):
    errors = []
    job_ops = {}
    for entry in schedule:
        job_ops.setdefault(entry['job'], []).append(entry)

    for j in range(n_jobs):
        ops = sorted(job_ops.get(j, []), key=lambda x: x['op'])
        if len(ops) != len(jobs[j]):
            errors.append(f"Job {j}: expected {len(jobs[j])} ops, got {len(ops)}")
            continue
        for o, op_entry in enumerate(ops):
            if op_entry['op'] != o:
                errors.append(f"Job {j}: missing op {o}")
                continue
            m, d = op_entry['machine'], op_entry['dur']
            if (m, d) not in jobs[j][o]:
                errors.append(f"Job {j} op {o}: (machine={m}, dur={d}) not in {jobs[j][o]}")
            if op_entry['end'] - op_entry['start'] != d:
                errors.append(f"Job {j} op {o}: end-start != dur")
            if o > 0:
                prev = ops[o-1]
                if op_entry['start'] < prev['end']:
                    errors.append(f"Job {j} op {o}: precedence violation")
            if overlaps_downtime(m, op_entry['start'], op_entry['end'], downtime):
                errors.append(f"Job {j} op {o}: downtime violation on machine {m}")

    machine_ops = {}
    for entry in schedule:
        machine_ops.setdefault(entry['machine'], []).append(entry)
    for m, ops in machine_ops.items():
        ops_sorted = sorted(ops, key=lambda x: x['start'])
        for i in range(len(ops_sorted) - 1):
            if ops_sorted[i]['end'] > ops_sorted[i+1]['start']:
                errors.append(f"Machine {m}: overlap")
    return errors

def validate_policy(schedule, baseline, policy, downtime):
    bl_lookup = build_baseline_lookup(baseline)
    freeze = policy.get('freeze', {})
    freeze_enabled = freeze.get('enabled', False)
    freeze_until = freeze.get('freeze_until', 0)
    lock_fields = freeze.get('lock_fields', [])
    budget = policy.get('change_budget', {})
    max_mc = budget.get('max_machine_changes', float('inf'))
    max_shift = budget.get('max_total_start_shift_L1', float('inf'))
    guards = policy.get('guards', {})
    max_ratio = guards.get('max_makespan_ratio', float('inf'))

    mc = 0
    shift = 0
    warnings = []

    for entry in schedule:
        key = (entry['job'], entry['op'])
        bl = bl_lookup.get(key)
        if bl is None:
            continue

        # Freeze check (only for ops that don't violate downtime in baseline)
        if freeze_enabled and bl['start'] < freeze_until:
            # Only enforce freeze if the baseline placement is feasible
            if not overlaps_downtime(bl['machine'], bl['start'], bl['end'], downtime):
                for field in lock_fields:
                    if entry[field] != bl[field]:
                        warnings.append(f"Freeze violation: J{entry['job']}O{entry['op']} {field}")

        if entry['machine'] != bl['machine']:
            mc += 1
        shift += abs(entry['start'] - bl['start'])

    makespan = max(e['end'] for e in schedule)

    if mc > max_mc:
        warnings.append(f"Machine changes {mc} > {max_mc}")
    if shift > max_shift:
        warnings.append(f"Start shift {shift} > {max_shift}")
    if makespan > baseline['makespan'] * max_ratio:
        warnings.append(f"Makespan ratio {makespan/baseline['makespan']:.2f} > {max_ratio}")

    return warnings, mc, shift

###############################################################################
# MAIN
###############################################################################
def main():
    n_jobs, n_machines, jobs = parse_instance('/app/data/instance.txt')
    downtime = parse_downtime('/app/data/downtime.csv')
    policy = parse_policy('/app/data/policy.json')
    baseline = parse_baseline('/app/data/baseline_solution.json')

    print(f"=== FJSP Solver ===")
    print(f"Problem: {n_jobs} jobs, {n_machines} machines (0,1,2)")
    print(f"\nJobs:")
    for j, ops in enumerate(jobs):
        for o, choices in enumerate(ops):
            print(f"  Job {j} Op {o}: {choices}")

    print(f"\nDowntime windows:")
    for m, windows in sorted(downtime.items()):
        for s, e in windows:
            print(f"  Machine {m}: [{s}, {e})")

    print(f"\nBaseline makespan: {baseline['makespan']}")
    print(f"Max allowed makespan (ratio {policy['guards']['max_makespan_ratio']}): "
          f"{baseline['makespan'] * policy['guards']['max_makespan_ratio']}")
    print(f"Max machine changes: {policy['change_budget']['max_machine_changes']}")
    print(f"Max total start shift L1: {policy['change_budget']['max_total_start_shift_L1']}")
    print(f"Freeze until: {policy['freeze']['freeze_until']}")

    # Check baseline violations
    violations = []
    for entry in baseline['schedule']:
        if overlaps_downtime(entry['machine'], entry['start'], entry['end'], downtime):
            violations.append(entry)
    print(f"\nBaseline downtime violations: {len(violations)}")
    for v in violations:
        print(f"  Job {v['job']} Op {v['op']} machine {v['machine']} [{v['start']},{v['end']})")

    # Solve
    print("\n=== Solving ===")
    best_schedule, best_makespan, best_info = solve(jobs, n_machines, downtime, baseline, policy)

    if best_schedule is None:
        print("ERROR: No feasible schedule found!")
        return

    best_schedule.sort(key=lambda x: (x['start'], x['job'], x['op']))
    print(f"\n=== Best Solution ===")
    print(f"Makespan: {best_makespan}")

    # Validate
    errors = validate_schedule(best_schedule, n_jobs, n_machines, jobs, downtime)
    if errors:
        print("VALIDATION ERRORS:")
        for e in errors:
            print(f"  {e}")
    else:
        print("Schedule feasibility: VALID")

    warnings, mc, shift = validate_policy(best_schedule, baseline, policy, downtime)
    print(f"Machine changes: {mc} / {policy['change_budget']['max_machine_changes']}")
    print(f"Total start shift: {shift} / {policy['change_budget']['max_total_start_shift_L1']}")
    if warnings:
        print("Policy warnings:")
        for w in warnings:
            print(f"  {w}")
    else:
        print("Policy: ALL SATISFIED")

    # Output
    os.makedirs('/app/output', exist_ok=True)

    solution = {
        "status": "FEASIBLE",
        "makespan": best_makespan,
        "schedule": best_schedule
    }

    with open('/app/output/solution.json', 'w') as f:
        json.dump(solution, f, indent=2)

    with open('/app/output/schedule.csv', 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['job', 'op', 'machine', 'start', 'end', 'dur'])
        writer.writeheader()
        for entry in best_schedule:
            writer.writerow(entry)

    print("\nFiles written:")
    print("  /app/output/solution.json")
    print("  /app/output/schedule.csv")

    print("\n=== FINAL SCHEDULE ===")
    for e in best_schedule:
        print(f"  Job {e['job']} Op {e['op']} -> M{e['machine']} [{e['start']}, {e['end']}) dur={e['dur']}")

if __name__ == '__main__':
    main()

