            if schedule is None or len(schedule) != sum(len(j) for j in jobs):
                continue

            makespan = max(e['end'] for e in schedule)

            if makespan >= best_makespan:
                continue

            if makespan > max_allowed_makespan:
                continue

            # Check start shift budget
            total_shift = sum(
                abs(e['start'] - bl_lookup[(e['job'], e['op'])]['start'])
                for e in schedule if (e['job'], e['op']) in bl_lookup
            )

            if total_shift > max_total_start_shift:
                continue

            # Validate no downtime violations
            valid = True
            for e in schedule:
                if overlaps_downtime(e['machine'], e['start'], e['end'], downtime):
