#!/usr/bin/env python3
"""
FJSP Solver v2 - Uses priority-dispatch with full enumeration of machine
assignments combined with priority-based dispatching.
"""

import json
import csv
import os
import itertools
from copy import deepcopy

###############################################################################
# PARSING
###############################################################################
def parse_instance(path):
    with open(path) as f:
        lines = [l.strip() for l in f if l.strip()]
    idx = 0
    n_jobs, n_machines = map(int, lines[idx].split())
    idx += 1
    jobs = []
    for j in range(n_jobs):
        n_ops = int(lines[idx]); idx += 1
        ops = []
        for o in range(n_ops):
            tokens = list(map(int, lines[idx].split())); idx += 1
            n_choices = tokens[0]
            choices = [(tokens[1+2*c], tokens[2+2*c]) for c in range(n_choices)]
            ops.append(choices)
        jobs.append(ops)
    return n_jobs, n_machines, jobs

def parse_downtime(path):
    downtime = {}
    with open(path) as f:
        reader = csv.DictReader(f)
        for row in reader:
            m, s, e = int(row['machine']), int(row['start']), int(row['end'])
            downtime.setdefault(m, []).append((s, e))
    return downtime

def parse_policy(path):
    with open(path) as f:
        return json.load(f)

def parse_baseline(path):
    with open(path) as f:
        return json.load(f)

###############################################################################
# HELPERS
###############################################################################
def overlaps_downtime(machine, start, end, downtime):
    for ds, de in downtime.get(machine, []):
        if start < de and end > ds:
            return True
    return False

def find_slot_on_machine(machine, earliest, duration, machine_timeline, downtime):
    start = earliest
    for _ in range(2000):
        end = start + duration
        conflict = False
        for ds, de in sorted(downtime.get(machine, [])):
            if start < de and end > ds:
                start = de
                conflict = True
                break
        if conflict:
            continue
        conflict = False
        for ms, me in sorted(machine_timeline):
            if start < me and end > ms:
                start = me
                conflict = True
                break
        if conflict:
            continue
        return start
    return start

def build_baseline_lookup(baseline):
    return {(e['job'], e['op']): e for e in baseline['schedule']}

def get_frozen_ops(baseline, policy, downtime):
    freeze = policy.get('freeze', {})
    if not freeze.get('enabled', False):
        return {}
    freeze_until = freeze.get('freeze_until', 0)
    frozen = {}
    for entry in baseline['schedule']:
        if entry['start'] < freeze_until:
            if not overlaps_downtime(entry['machine'], entry['start'], entry['end'], downtime):
                frozen[(entry['job'], entry['op'])] = entry
    return frozen

###############################################################################
# PRIORITY-DISPATCH SCHEDULING
###############################################################################
def dispatch_schedule(jobs, n_machines, downtime, frozen_ops, assignment, n_jobs):
    """
    Priority dispatch: at each step, among all ready operations (predecessor done),
    find the one that can finish earliest given machine assignment.
    """
    machine_timeline = {m: [] for m in range(n_machines)}
    job_end_time = {j: 0 for j in range(n_jobs)}
    next_op = {j: 0 for j in range(n_jobs)}
    schedule = []
    scheduled = set()
    n_total = sum(len(j) for j in jobs)

    # Place frozen ops (sorted by start time to maintain consistency)
    frozen_sorted = sorted(frozen_ops.items(), key=lambda x: x[1]['start'])
    for (j, o), entry in frozen_sorted:
        se = dict(entry)
        schedule.append(se)
        machine_timeline[entry['machine']].append((entry['start'], entry['end']))
        job_end_time[j] = max(job_end_time[j], entry['end'])
        scheduled.add((j, o))
        next_op[j] = max(next_op[j], o + 1)

    while len(schedule) < n_total:
        # Find ready operations
        candidates = []
        for j in range(n_jobs):
            o = next_op[j]
            if o < len(jobs[j]) and (j, o) not in scheduled:
                # Predecessor check
                if o == 0 or (j, o-1) in scheduled:
                    m, d = assignment[(j, o)]
                    earliest = job_end_time[j]
                    start = find_slot_on_machine(m, earliest, d, machine_timeline[m], downtime)
                    end = start + d
                    candidates.append((end, start, j, o, m, d))

        if not candidates:
            break

        # Pick the candidate that finishes earliest (ties broken by start, then job)
        candidates.sort()
        end, start, j, o, m, d = candidates[0]

        schedule.append({
            'job': j, 'op': o, 'machine': m,
            'start': start, 'end': end, 'dur': d
        })
        machine_timeline[m].append((start, end))
        job_end_time[j] = end
        scheduled.add((j, o))
        next_op[j] = o + 1

    return schedule

###############################################################################
# SOLVE WITH ALL MACHINE ASSIGNMENTS + DISPATCH
###############################################################################
def solve(jobs, n_machines, downtime, baseline, policy):
    n_jobs = len(jobs)
    bl_lookup = build_baseline_lookup(baseline)

    budget = policy.get('change_budget', {})
    max_mc = budget.get('max_machine_changes', float('inf'))
    max_shift = budget.get('max_total_start_shift_L1', float('inf'))
    guards = policy.get('guards', {})
    max_ratio = guards.get('max_makespan_ratio', float('inf'))
    max_allowed = baseline['makespan'] * max_ratio

    frozen_ops = get_frozen_ops(baseline, policy, downtime)
    print(f"Truly frozen ops: {list(frozen_ops.keys())}")

    ops_to_assign = []
    for j in range(n_jobs):
        for o in range(len(jobs[j])):
            if (j, o) not in frozen_ops:
                ops_to_assign.append((j, o))

    choice_lists = [jobs[j][o] for j, o in ops_to_assign]
    total = 1
    for cl in choice_lists:
        total *= len(cl)
    print(f"Machine combos: {total}")

    best_schedule = None
    best_makespan = float('inf')
    best_info = {}
    n_total_ops = sum(len(j) for j in jobs)

    for combo in itertools.product(*choice_lists):
        assignment = {}
        for i, (j, o) in enumerate(ops_to_assign):
            assignment[(j, o)] = combo[i]
        for (j, o), entry in frozen_ops.items():
            assignment[(j, o)] = (entry['machine'], entry['dur'])

        # Check mc budget
        mc = sum(1 for (j, o) in ops_to_assign
                 if (j, o) in bl_lookup and assignment[(j, o)][0] != bl_lookup[(j, o)]['machine'])
        if mc > max_mc:
            continue

        schedule = dispatch_schedule(jobs, n_machines, downtime, frozen_ops, assignment, n_jobs)
        if len(schedule) != n_total_ops:
            continue

        makespan = max(e['end'] for e in schedule)
        if makespan >= best_makespan or makespan > max_allowed:
            continue

        # Check shift
        shift = sum(
            abs(e['start'] - bl_lookup[(e['job'], e['op'])]['start'])
            for e in schedule if (e['job'], e['op']) in bl_lookup
        )
        if shift > max_shift:
            continue

        # Verify feasibility
        ok = True
        for e in schedule:
            if overlaps_downtime(e['machine'], e['start'], e['end'], downtime):
                ok = False; break
        if not ok:
            continue

        best_makespan = makespan
        best_schedule = schedule
        best_info = {'mc': mc, 'shift': shift}
        print(f"  New best: makespan={best_makespan}, mc={mc}, shift={shift}")

    # Also try with different dispatch rules
    # Rule 2: Most work remaining first
    print("\nTrying MWR dispatch...")
    for combo in itertools.product(*choice_lists):
        assignment = {}
        for i, (j, o) in enumerate(ops_to_assign):
            assignment[(j, o)] = combo[i]
        for (j, o), entry in frozen_ops.items():
            assignment[(j, o)] = (entry['machine'], entry['dur'])

        mc = sum(1 for (j, o) in ops_to_assign
                 if (j, o) in bl_lookup and assignment[(j, o)][0] != bl_lookup[(j, o)]['machine'])
        if mc > max_mc:
            continue

        schedule = mwr_dispatch(jobs, n_machines, downtime, frozen_ops, assignment, n_jobs)
        if len(schedule) != n_total_ops:
            continue

        makespan = max(e['end'] for e in schedule)
        if makespan >= best_makespan or makespan > max_allowed:
            continue

        shift = sum(
            abs(e['start'] - bl_lookup[(e['job'], e['op'])]['start'])
            for e in schedule if (e['job'], e['op']) in bl_lookup
        )
        if shift > max_shift:
            continue

        ok = True
        for e in schedule:
            if overlaps_downtime(e['machine'], e['start'], e['end'], downtime):
                ok = False; break
        if not ok:
            continue

        best_makespan = makespan
        best_schedule = schedule
        best_info = {'mc': mc, 'shift': shift}
        print(f"  New best (MWR): makespan={best_makespan}, mc={mc}, shift={shift}")

    return best_schedule, best_makespan, best_info


def mwr_dispatch(jobs, n_machines, downtime, frozen_ops, assignment, n_jobs):
    """Most Work Remaining dispatch rule."""
    machine_timeline = {m: [] for m in range(n_machines)}
    job_end_time = {j: 0 for j in range(n_jobs)}
    next_op = {j: 0 for j in range(n_jobs)}
    schedule = []
    scheduled = set()
    n_total = sum(len(j) for j in jobs)

    frozen_sorted = sorted(frozen_ops.items(), key=lambda x: x[1]['start'])
    for (j, o), entry in frozen_sorted:
        se = dict(entry)
        schedule.append(se)
        machine_timeline[entry['machine']].append((entry['start'], entry['end']))
        job_end_time[j] = max(job_end_time[j], entry['end'])
        scheduled.add((j, o))
        next_op[j] = max(next_op[j], o + 1)

    def remaining_work(j):
        total = 0
        for o in range(next_op[j], len(jobs[j])):
            m, d = assignment[(j, o)]
            total += d
        return total

    while len(schedule) < n_total:
        candidates = []
        for j in range(n_jobs):
            o = next_op[j]
            if o < len(jobs[j]) and (j, o) not in scheduled:
                if o == 0 or (j, o-1) in scheduled:
                    m, d = assignment[(j, o)]
                    earliest = job_end_time[j]
                    start = find_slot_on_machine(m, earliest, d, machine_timeline[m], downtime)
                    end = start + d
                    rw = remaining_work(j)
                    candidates.append((-rw, start, j, o, m, d, end))

        if not candidates:
            break

        candidates.sort()
        _, start, j, o, m, d, end = candidates[0]

        schedule.append({
            'job': j, 'op': o, 'machine': m,
            'start': start, 'end': end, 'dur': d
        })
        machine_timeline[m].append((start, end))
        job_end_time[j] = end
        scheduled.add((j, o))
        next_op[j] = o + 1

    return schedule


###############################################################################
# VALIDATION
###############################################################################
def validate_schedule(schedule, n_jobs, n_machines, jobs, downtime):
    errors = []
    job_ops = {}
    for entry in schedule:
        job_ops.setdefault(entry['job'], []).append(entry)
    for j in range(n_jobs):
        ops = sorted(job_ops.get(j, []), key=lambda x: x['op'])
        if len(ops) != len(jobs[j]):
            errors.append(f"Job {j}: wrong op count"); continue
        for o, oe in enumerate(ops):
            if oe['op'] != o:
                errors.append(f"Job {j}: missing op {o}"); continue
            if (oe['machine'], oe['dur']) not in jobs[j][o]:
                errors.append(f"Job {j} op {o}: invalid machine/dur")
            if oe['end'] - oe['start'] != oe['dur']:
                errors.append(f"Job {j} op {o}: dur mismatch")
            if o > 0 and oe['start'] < ops[o-1]['end']:
                errors.append(f"Job {j} op {o}: precedence violation")
            if overlaps_downtime(oe['machine'], oe['start'], oe['end'], downtime):
                errors.append(f"Job {j} op {o}: downtime on M{oe['machine']}")
    machine_ops = {}
    for e in schedule:
        machine_ops.setdefault(e['machine'], []).append(e)
    for m, ops in machine_ops.items():
        ops.sort(key=lambda x: x['start'])
        for i in range(len(ops)-1):
            if ops[i]['end'] > ops[i+1]['start']:
                errors.append(f"M{m}: overlap")
    return errors

###############################################################################
# MAIN
###############################################################################
def main():
    n_jobs, n_machines, jobs = parse_instance('/app/data/instance.txt')
    downtime = parse_downtime('/app/data/downtime.csv')
    policy = parse_policy('/app/data/policy.json')
    baseline = parse_baseline('/app/data/baseline_solution.json')

    print(f"=== FJSP Solver v2 ===")
    print(f"{n_jobs} jobs, {n_machines} machines")
    print(f"Downtime: {downtime}")
    print(f"Baseline makespan: {baseline['makespan']}")
    print(f"Max makespan: {baseline['makespan'] * policy['guards']['max_makespan_ratio']}")

    best_schedule, best_makespan, best_info = solve(jobs, n_machines, downtime, baseline, policy)

    if best_schedule is None:
        print("No feasible schedule found!")
        return

    best_schedule.sort(key=lambda x: (x['start'], x['job'], x['op']))

    errors = validate_schedule(best_schedule, n_jobs, n_machines, jobs, downtime)
    print(f"\nMakespan: {best_makespan}")
    print(f"Validation: {'PASS' if not errors else 'FAIL'}")
    if errors:
        for e in errors:
            print(f"  {e}")
    print(f"Machine changes: {best_info.get('mc', '?')}")
    print(f"Start shift: {best_info.get('shift', '?')}")

    os.makedirs('/app/output', exist_ok=True)

    solution = {
        "status": "FEASIBLE",
        "makespan": best_makespan,
        "schedule": best_schedule
    }

    with open('/app/output/solution.json', 'w') as f:
        json.dump(solution, f, indent=2)

    with open('/app/output/schedule.csv', 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['job', 'op', 'machine', 'start', 'end', 'dur'])
        writer.writeheader()
        for entry in best_schedule:
            writer.writerow(entry)

    print("\n=== FINAL SCHEDULE ===")
    for e in best_schedule:
        print(f"  J{e['job']}O{e['op']} -> M{e['machine']} [{e['start']},{e['end']}) d={e['dur']}")

    print("\nDone.")

if __name__ == '__main__':
